def minimumIndex(capacity, itemSize):
    # Index of the best (smallest fitting) box so far, -1 if none yet
    best = -1
    for i, c in enumerate(capacity):
        # Only boxes that can hold the item are candidates
        if c >= itemSize:
            # Strict < keeps the earliest index among equal capacities
            if best == -1 or c < capacity[best]:
                best = i
    return best
